DENTITY(1,1) NOT NULL,\r\n\t[cantidad] [int] NULL,\r\n\t[precio_unitario] [decimal](20, 2) NULL,\r\n\t[id_venta] [int] NOT NULL,\r\n\t[Id_producto] [int] NOT NULL\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Detalle_Venta' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Puesto]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Puesto' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Puesto] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Puesto](\r\n\t[Id_puesto] [int] IDENTITY(1,1) NOT NULL,\r\n\t[horario_cierre] [time](7) NULL,\r\n\t[horario_apertura] [time](7) NULL,\r\n\t[estado] [varchar](20) NULL,\r\n\t[categoria] [char](10) NULL,\r\n\t[numero_puesto] [varchar](10) NULL,\r\n\t[ubicacion_sector] [varchar](100) NULL,\r\n\t[nombre_puesto] [varchar](100) NULL\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Puesto' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Vendedor]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Vendedor' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Vendedor] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Vendedor](\r\n\t[Id_vendedor] [int] IDENTITY(1,1) NOT NULL,\r\n\t[telefono] [varchar](15) NULL,\r\n\t[nombre] [varchar](50) NULL,\r\n\t[rol] [varchar](30) NULL,\r\n\t[Apellido_M] [varchar](50) NULL,\r\n\t[Apellido_p] [varchar](50) NULL,\r\n\t[id_usuario] [int] NOT NULL,\r\n\t[activo] [bit] NOT NULL\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Vendedor' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Venta]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Venta' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Venta] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Venta](\r\n\t[id_venta] [int] IDENTITY(1,1) NOT NULL,\r\n\t[Id_vendedor] [int] NOT NULL,\r\n\t[fecha_hora] [datetime] NULL,\r\n\t[metodo_pago] [varchar](30) NULL,\r\n\t[Id_puesto] [int] NOT NULL,\r\n\t[id_cliente] [int] NOT NULL\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Venta' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_ResumenVenta]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/View[@Name='vw_ResumenVenta' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: View [dbo].[vw_ResumenVenta] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\nCREATE VIEW [dbo].[vw_ResumenVenta] AS\nSELECT \n    V.id_venta, \n    V.fecha_hora AS Fecha, \n    V.metodo_pago AS MetodoPago, \n    C.nombre AS Cliente, \n    VD.nombre AS Vendedor, \n    P.nombre_puesto AS Puesto,\n    (SELECT ISNULL(SUM(DV.cantidad * DV.precio_unitario), 0) \n     FROM Detalle_Venta DV \n     WHERE DV.id_venta = V.id_venta) AS PrecioTotal\nFROM Venta V\nINNER JOIN Cliente C ON V.id_cliente = C.id_cliente\nINNER JOIN Puesto P ON V.Id_puesto = P.Id_puesto\nLEFT JOIN Vendedor VD ON V.Id_vendedor = VD.Id_vendedor;\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/View[@Name='vw_ResumenVenta' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[ventas_por_puesto]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/View[@Name='ventas_por_puesto' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: View [dbo].[ventas_por_puesto] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\nCREATE VIEW [dbo].[ventas_por_puesto] AS\nSELECT \n    p.Id_puesto AS id_puesto,\n    p.nombre_puesto,\n    p.numero_puesto,\n    ISNULL(SUM(dv.cantidad * dv.precio_unitario), 0) AS total_ventas,\n    COUNT(DISTINCT v.id_venta) AS transacciones_totales\nFROM \n    Puesto p\nLEFT JOIN \n    Venta v ON p.Id_puesto = v.Id_puesto\nLEFT JOIN \n    Detalle_Venta dv ON v.id_venta = dv.id_venta\nGROUP BY \n    p.Id_puesto, \n    p.nombre_puesto, \n    p.numero_puesto;\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/View[@Name='ventas_por_puesto' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Artesano]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Artesano' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Artesano] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Artesano](\r\n\t[id_artesano] [int] IDENTITY(1,1) NOT NULL,\r\n\t[foto_perfil] [varchar](max) NULL,\r\n\t[biografia] [varchar](250) NULL,\r\n\t[fecha_registro] [date] NULL,\r\n\t[años_experiencia] [int] NULL,\r\n\t[telefono] [varchar](15) NULL,\r\n\t[apellido_materno] [varchar](50) NULL,\r\n\t[apellido_paterno] [varchar](50) NULL,\r\n\t[nombre] [varchar](50) NULL,\r\n\t[id_cueva] [int] NOT NULL,\r\n\t[id_usuario] [int] NOT NULL,\r\n\t[Id_puesto] [int] NOT NULL,\r\n\t[activo] [bit] NOT NULL\r\n) ON [PRIMARY] TEXTIMAGE_ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Artesano' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Calidad]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Calidad' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Calidad] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Calidad](\r\n\t[id_calidad] [int] IDENTITY(1,1) NOT NULL,\r\n\t[nombre_calidad] [varchar](50) NULL,\r\n\t[dias_elaboracion_estimados] [int] NULL,\r\n\t[numero_partidas] [int] NULL\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Calidad' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Categoria_Estilo]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Categoria_Estilo' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Categoria_Estilo] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Categoria_Estilo](\r\n\t[id_estilo] [int] IDENTITY(1,1) NOT NULL,\r\n\t[descripcion] [text] NULL,\r\n\t[nombre_estilo] [varchar](50) NULL\r\n) ON [PRIMARY] TEXTIMAGE_ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Categoria_Estilo' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Producto]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Producto' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Producto] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Producto](\r\n\t[Id_producto] [int] IDENTITY(1,1) NOT NULL,\r\n\t[imagen_url] [varchar](max) NULL,\r\n\t[descripcion] [varchar](250) NULL,\r\n\t[Num_partida] [int] NULL,\r\n\t[talla] [varchar](10) NULL,\r\n\t[color] [varchar](30) NULL,\r\n\t[nombre] [varchar](100) NULL,\r\n\t[tipo_tejido] [varchar](30) NULL,\r\n\t[precio_base] [decimal](20, 2) NULL,\r\n\t[Material] [varchar](30) NULL,\r\n\t[id_artesano] [int] NOT NULL,\r\n\t[id_estilo] [int] NOT NULL,\r\n\t[id_calidad] [int] NOT NULL,\r\n\t[activo] [bit] NOT NULL\r\n) ON [PRIMARY] TEXTIMAGE_ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Producto' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_CatalogoProductos]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/View[@Name='vw_CatalogoProductos' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: View [dbo].[vw_CatalogoProductos] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE VIEW [dbo].[vw_CatalogoProductos] AS\r\nSELECT\r\n    p.Id_producto,\r\n    p.nombre                                   AS Producto,\r\n    e.nombre_estilo                            AS Estilo,\r\n    c.nombre_calidad                           AS Calidad,\r\n    CONCAT(a.nombre, ' ', a.apellido_paterno)  AS Artesano,\r\n    p.precio_base                              AS Precio\r\nFROM Producto p\r\nINNER JOIN Categoria_Estilo e ON p.id_estilo   = e.id_estilo\r\nINNER JOIN Calidad          c ON p.id_calidad  = c.id_calidad\r\nINNER JOIN Artesano         a ON p.id_artesano = a.id_artesano\r\nWHERE p.activo = 1;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/View[@Name='vw_CatalogoProductos' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Inventario]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Inventario' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Inventario] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Inventario](\r\n\t[id_inventario] [int] IDENTITY(1,1) NOT NULL,\r\n\t[fecha_actualizacion] [datetime] NULL,\r\n\t[stock_minimo] [int] NULL,\r\n\t[stock_actual] [int] NULL,\r\n\t[Id_puesto] [int] NOT NULL,\r\n\t[Id_producto] [int] NOT NULL\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Inventario' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_StockPorPuesto]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/View[@Name='vw_StockPorPuesto' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: View [dbo].[vw_StockPorPuesto] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE VIEW [dbo].[vw_StockPorPuesto] AS\r\nSELECT\r\n    pu.nombre_puesto  AS Puesto,\r\n    pr.nombre         AS Producto,\r\n    i.stock_actual    AS StockActual,\r\n    i.stock_minimo    AS StockMinimo,\r\n    CASE WHEN i.stock_actual <= i.stock_minimo\r\n         THEN 'Reabastecer' ELSE 'Suficiente' END AS Estado\r\nFROM Inventario i\r\nINNER JOIN Puesto   pu ON i.Id_puesto   = pu.Id_puesto\r\nINNER JOIN Producto pr ON i.Id_producto = pr.Id_producto;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/View[@Name='vw_StockPorPuesto' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Asignacion_Puesto]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Asignacion_Puesto' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Asignacion_Puesto] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Asignacion_Puesto](\r\n\t[id_asignacion] [int] IDENTITY(1,1) NOT NULL,\r\n\t[Id_vendedor] [int] NOT NULL,\r\n\t[turno] [varchar](30) NULL,\r\n\t[fecha_fin] [date] NULL,\r\n\t[fecha_inicio] [date] NULL,\r\n\t[Id_puesto] [int] NOT NULL,\r\n\t[estado] [varchar](20) NOT NULL\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Asignacion_Puesto' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Cueva]"],"metadata":{"urn":"Server[@Name='Yuriko']/Database[@Name='Artesanos_Becal_3']/Table[@Name='Cueva' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: Table [dbo].[Cueva] Fecha de script: 27/10/2026 01:35:57 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Cueva](\r\n\t[id_cueva] [int] IDENTITY(1,1) NOT NULL,\r\n\t[direccion_ubicacion] [varchar](200) NULL,\r\n\t[tipo_cueva] [varchar](50) NULL,\r\n\t[nombre_cueva] [varchar](100) N